from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def _ledger(data, sequence_first, discounted):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        rev = event.get("revision", 0)
        key = (seq, rev, pos) if sequence_first else (rev, pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n):
        return (n + 5000) // 10000 if mode == "half_up" else n // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = net if discounted else raw
        tax = rounded(base * event.get("tax_bp", 0))
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        rows = [r for r in packages[name]
                if r["version"] not in blocked.get(name, [])
                and (name not in pins or r["version"] == pins[name])]
        options.append([None] + rows)

    best_vector = None
    best_versions = None
    for choices in product(*options):
        assigned = {name: row for name, row in zip(names, choices) if row is not None}
        if any(name not in assigned or not bounds[0] <= assigned[name]["version"] <= bounds[1]
               for name, bounds in data["roots"].items()):
            continue

        edges = {}
        closure = set()
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            closure.add(name)
            row = assigned.get(name)
            if row is None:
                valid = False
                break
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                target = assigned.get(other)
                if target is None or not dep["min"] <= target["version"] <= dep["max"]:
                    valid = False
                    break
                active.append(other)
                pending.append(other)
            edges[name] = active
        if not valid or closure != set(assigned):
            continue

        visiting, finished = set(), set()
        def acyclic(name):
            if name in visiting:
                return False
            if name in finished:
                return True
            visiting.add(name)
            if any(not acyclic(dep) for dep in edges.get(name, [])):
                return False
            visiting.remove(name)
            finished.add(name)
            return True
        if not all(acyclic(name) for name in closure):
            continue

        vector = tuple(assigned[name]["version"] if name in assigned else -1
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best_versions = {name: row["version"] for name, row in assigned.items()}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    available = [j for j in jobs if j["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for subset in combinations(available, k):
        ids = {j["id"] for j in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active_ends = []
        ok = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
            while active_ends and active_ends[0] <= job["start"]:
                heapq.heappop(active_ends)
            heapq.heappush(active_ends, job["end"])
            if len(active_ends) > 2:
                ok = False
                break
        if not ok:
            continue
        value = sum(j["value"] for j in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and selected > best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit_for = {}
    for i, node in enumerate(required):
        bit_for[node] = bit_for.get(node, 0) | (1 << i)
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    source = data["source"]
    initial_mask = bit_for.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            next_mask = mask | bit_for.get(edge["v"], 0)
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, coupons_left in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, coupons_left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, coupons_left))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: _ledger(d, False, False),
    "component_02": lambda d: _ledger(d, True, False),
    "component_03": lambda d: _ledger(d, False, True),
    "component_04": lambda d: _ledger(d, True, True),
    "component_05": lambda d: _ledger(d, False, False),
    "component_06": _resolver,
    "component_07": _jobs,
    "component_08": _routes,
}
